/**
 * The accounts signed-in tests sign in with (G-159), one per role, never in the code, a log or a
 * failure's evidence. Each is looked up in this order:
 * <ol>
 * <li>the environment: SUITE_USER_USERNAME and SUITE_USER_PASSWORD (SUITE_ADMIN_... for admin), as a
 *     pipeline or a tracker app sets them;
 * <li>docked (this suite in Suite Builder's dock), Suite Builder's own store, in Suite Builder's folder
 *     (the dock's DOCK.md names it, G-163): &lt;site&gt;/&lt;role&gt;.login, the account the crawl signed in with;
 * <li>this suite's own secrets/&lt;role&gt;.login.
 * </ol>
 * A file is two lines, Username: and Password:, each value everything after the first colon. The
 * secrets folder is never committed (SR-20); a copy of the suite handed on carries its files blank.
 */
public final class Credentials {
    /** The suite's own account files, one per role. */
    public static final Path FOLDER = Path.of("secrets");
    /** A blank account file: what a person fills in. */
    public static final String BLANK = "Username:\nPassword:\n";

    private Credentials() {
    }

    /** An account: what is typed to sign in, and where it came from. Printing it never shows it. */
    public static final class Account {
        private final String username;
        private final String password;
        private final String from;

        Account(String username, String password, String from) {
            this.username = username;
            this.password = password;
            this.from = from;
        }

        public String username() {
            return username;
        }

        public String password() {
            return password;
        }

        /** Where it came from: the environment variables, or the file's path. */
        public String from() {
            return from;
        }

        @Override
        public String toString() {
            return "the account in " + from;
        }
    }

    /** The role's account; fails at once, saying where to put one, when none is set. */
    public static Account of(String role) {
        String r = role.toUpperCase(Locale.ROOT).replaceAll("[^A-Z0-9]", "_");
        String user = env("SUITE_" + r + "_USERNAME");
        String pass = env("SUITE_" + r + "_PASSWORD");
        if (user != null && pass != null) return new Account(user, pass, "SUITE_" + r + "_USERNAME and SUITE_" + r + "_PASSWORD");
        Path kept = store();
        Path store = kept == null ? null : kept.resolve(site()).resolve(role + ".login");
        if (store != null) {
            Account account = read(store);
            if (account != null) return account;
        }
        Account own = read(FOLDER.resolve(role + ".login"));
        if (own != null) return own;
        throw new AssertionError("This test signs in as " + role + ": fill in " + FOLDER.resolve(role + ".login") + " (Username: and Password:), or set SUITE_"
                + r + "_USERNAME and SUITE_" + r + "_PASSWORD" + (store != null ? ", or fill in Suite Builder's " + store : "") + ". Never write an account into the code.");
    }

    /** Every role's account file, blank, where there is none: once a run, before the first test (BaseTest). */
    public static void blankFiles(List<String> roles) {
        try {
            Files.createDirectories(FOLDER);
            for (String role : roles) {
                Path file = FOLDER.resolve(role + ".login");
                if (!Files.exists(file)) Files.writeString(file, BLANK, StandardCharsets.UTF_8);
            }
        } catch (IOException e) {
            System.out.println("   note: could not write the blank account files in " + FOLDER + ": " + e.getMessage());
        }
    }

    /** True when this suite sits in Suite Builder's dock: its folder's folder holds the dock's DOCK.md. */
    static boolean docked() {
        Path parent = Path.of("").toAbsolutePath().getParent();
        return parent != null && Files.isRegularFile(parent.resolve("DOCK.md"));
    }

    /**
     * Suite Builder's store: the folder SUITE_BUILDER_SECRETS names, else, docked, the one the dock's DOCK.md
     * names on its last line (Accounts: ...), in Suite Builder's own folder (G-163); null otherwise.
     */
    static Path store() {
        String set = env("SUITE_BUILDER_SECRETS");
        if (set != null) return Path.of(set);
        if (!docked()) return null;
        try {
            for (String line : Files.readAllLines(Path.of("").toAbsolutePath().getParent().resolve("DOCK.md"), StandardCharsets.UTF_8)) {
                if (line.startsWith("Accounts: ")) return Path.of(line.substring("Accounts: ".length()).trim());
            }
        } catch (IOException e) {
            return null;
        }
        return null;
    }

    /** The site's name in the store: the crawled site's host, without www. */
    static String site() {
        String host = URI.create(SiteConfig.CRAWLED_URL).getHost();
        return host != null && host.startsWith("www.") ? host.substring(4) : String.valueOf(host);
    }

    /** A file's account, when both of its values are filled in; null otherwise. */
    static Account read(Path file) {
        if (!Files.isRegularFile(file)) return null;
        String username = "";
        String password = "";
        try {
            for (String line : Files.readAllLines(file, StandardCharsets.UTF_8)) {
                int colon = line.indexOf(':');
                if (colon < 0) continue;
                String key = line.substring(0, colon).trim().toLowerCase(Locale.ROOT);
                if (key.equals("username")) username = line.substring(colon + 1).trim();
                if (key.equals("password")) password = line.substring(colon + 1).trim();
            }
        } catch (IOException e) {
            return null;
        }
        return username.isEmpty() || password.isEmpty() ? null : new Account(username, password, file.toString());
    }

    private static String env(String name) {
        String value = System.getenv(name);
        return value == null || value.isBlank() ? null : value.trim();
    }
}
